/**
 * GPU-accelerated SDF (Signed Distance Field) generator for point clouds using PointsBVH.
 *
 * **Overview**
 * Generates a 3D texture containing distances from a point cloud surface.
 * Uses PointsBVH (from three-mesh-bvh) for O(log N) nearest-point queries.
 * The "surface" is defined by a shell radius around each point.
 *
 * **Features**
 * - **Fast Generation**: Uses compute shaders to generate SDFs in parallel.
 * - **PointsBVH Acceleration**: Leverages `three-mesh-bvh` PointsBVH for efficient queries.
 * - **Shell Radius**: Defines surface thickness around points (auto-computed or user-specified).
 * - **Auto Shell Radius**: Estimates optimal radius from point cloud density.
 *
 * **Usage**
 * The generated 3D texture can be used for:
 * - **Volume Rendering**: Raymarching point cloud isosurfaces.
 * - **Collision Detection**: GPU-based particle collisions.
 * - **VFX**: Distance-based effects around point cloud surfaces.
 *
 * @example
 * import { PointsBVH } from 'three-mesh-bvh';
 * import { ComputePointsSDFGenerator } from '@three-blocks/core';
 *
 * // 1. Build PointsBVH
 * const geometry = new THREE.BufferGeometry();
 * geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
 * geometry.computeBoundsTree({ type: PointsBVH });
 *
 * // 2. Create SDF Generator
 * const sdfGen = new ComputePointsSDFGenerator({
 *   resolution: 64,
 *   margin: 0.2,
 *   shellRadius: 'auto' // or specific value like 0.05
 * });
 *
 * // 3. Generate SDF Texture
 * await sdfGen.generate(geometry, geometry.boundsTree, renderer);
 * const sdfTexture = sdfGen.sdfTexture;
 *
 * @class ComputePointsSDFGenerator
 * @short GPU SDF generator that builds a 3D distance texture from a point cloud using PointsBVH.
 * @category Compute
 * @tags WebGPU, PointCloud
 */
export class ComputePointsSDFGenerator {
    /**
     * Create a new point cloud SDF generator.
     *
     * @param {Object} [options] - Configuration options.
     * @param {number} [options.resolution=64] - SDF grid resolution (resolution^3 voxels). Higher is more detailed but slower.
     * @param {number} [options.margin=0.2] - Extra margin around point cloud bounds to capture the field.
     * @param {number} [options.threshold=0.0] - Distance threshold (bias) applied to the SDF.
     * @param {number|'auto'} [options.shellRadius='auto'] - Surface thickness around points. 'auto' estimates from point density.
     * @param {THREE.Box3} [options.bounds] - Custom bounds for the SDF volume. Auto-computed from geometry if not provided.
     * @param {THREE.Vector3} [options.workgroupSize=Vector3(4,4,4)] - Compute shader workgroup size. Tweak for performance.
     */
    constructor(options?: {
        resolution?: number;
        margin?: number;
        threshold?: number;
        shellRadius?: number | "auto";
        bounds?: THREE.Box3;
        workgroupSize?: THREE.Vector3;
    });
    /** @type {number} */
    resolution: number;
    /** @type {number} */
    margin: number;
    /** @type {number} */
    threshold: number;
    /** @type {number|'auto'} */
    shellRadiusOption: number | "auto";
    /** @type {number} */
    _shellRadius: number;
    /** @type {THREE.Box3 | null} */
    customBounds: THREE.Box3 | null;
    /** @type {THREE.Vector3} */
    workgroupSize: THREE.Vector3;
    /** @type {THREE.Storage3DTexture | null} */
    _sdfTexture: THREE.Storage3DTexture | null;
    /** @type {THREE.Matrix4} */
    _boundsMatrix: THREE.Matrix4;
    /** @type {THREE.Matrix4} */
    _inverseBoundsMatrix: THREE.Matrix4;
    /** @type {THREE.Box3} */
    _bounds: THREE.Box3;
    /** @type {THREE.Box3} */
    _geometryBounds: THREE.Box3;
    /** @type {*} */
    _computeKernel: any;
    /** @type {boolean} */
    _initialized: boolean;
    /** @private */
    private _uMatrix;
    /** @private */
    private _uDim;
    /** @private */
    private _uThreshold;
    /** @private */
    private _uShellRadius;
    /**
     * Generates SDF texture from point cloud geometry and PointsBVH.
     *
     * @param {THREE.BufferGeometry} geometry - Source geometry with position attribute
     * @param {PointsBVH} bvh - PointsBVH from three-mesh-bvh
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @returns {Promise<THREE.Storage3DTexture>} Generated SDF texture
     */
    generate(geometry: THREE.BufferGeometry, bvh: PointsBVH, renderer: THREE.WebGPURenderer): Promise<THREE.Storage3DTexture>;
    /**
     * Updates SDF texture with potentially modified point cloud/BVH.
     * More efficient than full regeneration if structure hasn't changed.
     *
     * @param {THREE.BufferGeometry} geometry - Source geometry
     * @param {PointsBVH} bvh - PointsBVH from three-mesh-bvh
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @returns {Promise<THREE.Storage3DTexture>} Updated SDF texture
     */
    update(geometry: THREE.BufferGeometry, bvh: PointsBVH, renderer: THREE.WebGPURenderer): Promise<THREE.Storage3DTexture>;
    /**
     * Computes shell radius from point cloud density.
     * Uses average nearest-neighbor distance estimation.
     * @private
     * @param {THREE.BufferGeometry} geometry
     */
    private _computeShellRadius;
    /**
     * Computes bounding box with margin.
     * @private
     * @param {THREE.BufferGeometry} geometry
     */
    private _computeBounds;
    /**
     * Initializes or recreates the Storage3DTexture.
     * @private
     */
    private _initializeTexture;
    /**
     * Builds the compute shader for SDF generation from point cloud.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {PointsBVH} bvh
     */
    private _buildComputeShader;
    _geomIndex: any;
    _geomPosition: any;
    _bvhNodes: any;
    /**
     * Updates geometry buffers (for dynamic point clouds).
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {PointsBVH} bvh
     */
    private _updateGeometryBuffers;
    /**
     * Gets or generates index array for the geometry.
     * For PointsBVH, indices are single uint values (one per point).
     * PointsBVH uses _indirectBuffer for primitive ordering (unlike MeshBVH which modifies geometry.index).
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {PointsBVH} bvh
     * @returns {Uint32Array}
     */
    private _getIndexArray;
    /**
     * Generates sequential indices for non-indexed geometry.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Uint32Array}
     */
    private _generateIndices;
    /**
     * Ensures vertex position data is Float32Array.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Float32Array}
     */
    private _getPositionArray;
    /**
     * Gets the generated SDF texture.
     * @returns {THREE.Storage3DTexture | null}
     */
    get sdfTexture(): THREE.Storage3DTexture | null;
    /**
     * Sets the shell radius (triggers regeneration on next generate call).
     * @param {number|'auto'} value
     */
    set shellRadius(value: number | "auto");
    /**
     * Gets the computed shell radius.
     * @returns {number}
     */
    get shellRadius(): number;
    /**
     * Gets the bounds transformation matrix (local to world).
     * @returns {THREE.Matrix4}
     */
    get boundsMatrix(): THREE.Matrix4;
    /**
     * Gets the inverse bounds matrix (world to local).
     * @returns {THREE.Matrix4}
     */
    get inverseBoundsMatrix(): THREE.Matrix4;
    /**
     * Gets the computed bounding box (includes margin).
     * @returns {THREE.Box3}
     */
    get bounds(): THREE.Box3;
    /**
     * Gets the tight geometry bounding box (without margin).
     * @returns {THREE.Box3}
     */
    get geometryBounds(): THREE.Box3;
    /**
     * Disposes GPU resources.
     */
    dispose(): void;
}
